"""Independent reference implementation for cross-checking (test-only).

Deliberately written with different structures/algorithm choices than
submission/main.py: full atom product (no simplification, no component
reduction), recursive AST evaluation, Moore partition refinement.
"""

import json


# ---------------------------------------------------------------- monitors

def ref_monitor(op, path, tokens):
    m = len(path)
    n = len(tokens)
    trans = []
    true_state = m
    if op in ('match', 'startswith'):
        nstates = m + 2
        dead = nstates - 1
        for k in range(nstates):
            row = []
            for t in range(n):
                if k < m:
                    row.append(k + 1 if tokens[t] == path[k] else dead)
                elif k == m:
                    row.append(m if op == 'startswith' else dead)
                else:
                    row.append(dead)
            trans.append(row)
        return trans, true_state
    # endswith / contains
    nstates = m + 1
    for k in range(nstates):
        row = []
        for t in range(n):
            seq = list(path[:k]) + [tokens[t]]
            best = 0
            for j in range(min(k + 1, m), -1, -1):
                if list(path[:j]) == seq[len(seq) - j:]:
                    best = j
                    break
            if op == 'contains' and best == m:
                best = m
            row.append(m if (op == 'contains' and k == m) else best)
        trans.append(row)
    return trans, true_state


def ref_eval(node, truth):
    op = node['op']
    if op == 'true':
        return True
    if op == 'false':
        return False
    if op == 'not':
        return not ref_eval(node['arg'], truth)
    if op == 'and':
        return all(ref_eval(a, truth) for a in node['args'])
    if op == 'or':
        return any(ref_eval(a, truth) for a in node['args'])
    return truth[(op, tuple(node['path']))]


def ref_atoms(node, out):
    op = node['op']
    if op in ('match', 'startswith', 'endswith', 'contains'):
        key = (op, tuple(node['path']))
        out.setdefault(key, len(out))
    elif op == 'not':
        ref_atoms(node['arg'], out)
    elif op in ('and', 'or'):
        for a in node['args']:
            ref_atoms(a, out)


def ref_compile(services, rules, queries):
    n = len(services)
    atoms = {}
    for r in rules:
        ref_atoms(r['when'], atoms)
    keys = list(atoms)
    mons = [ref_monitor(op, list(path), services) for (op, path) in keys]
    if not mons:
        truth0 = {}
        start_acc = any(ref_eval(r['when'], truth0) for r in rules
                        if r['action'] == 'allow') and not any(
            ref_eval(r['when'], truth0) for r in rules if r['action'] == 'drop')
        nexts = [[] for _ in range(1)]
        acc = [start_acc]
    else:
        start = tuple([0] * len(mons))
        seen = {start: 0}
        order = [start]
        trans = []
        acc = []
        idx = 0
        while idx < len(order):
            st = order[idx]
            truth = {}
            for i, (t, ts) in enumerate(mons):
                truth[keys[i]] = (st[i] == ts)
            ok = any(ref_eval(r['when'], truth) for r in rules
                     if r['action'] == 'allow') and not any(
                ref_eval(r['when'], truth) for r in rules
                if r['action'] == 'drop')
            acc.append(ok)
            row = []
            for t in range(n):
                nxt = tuple(mons[i][0][st[i]][t] for i in range(len(mons)))
                if nxt not in seen:
                    seen[nxt] = len(order)
                    order.append(nxt)
                row.append(seen[nxt])
            trans.append(row)
            idx += 1
        nexts, acc = ref_minimize(trans, acc, n)

    dist = ref_distance(nexts, acc, n)
    tidx = {s: i for i, s in enumerate(services)}
    qout = []
    for path in queries:
        st = 0
        for tok in path:
            if n:
                st = nexts[st][tidx[tok]]
        qout.append({'state': st, 'allow': acc[st], 'distance': dist[st]})
    return {'ok': True, 'dfa': {'start': 0, 'accept': acc, 'next': nexts,
                                'distance': dist}, 'queries': qout}


def ref_minimize(trans, acc, n):
    nst = len(trans)
    blocks = {}
    block_of = [0] * nst
    for s in range(nst):
        key = acc[s]
        if key not in blocks:
            blocks[key] = len(blocks)
        block_of[s] = blocks[key]
    nblocks = len(blocks)
    while True:
        sig = {}
        block_of2 = [0] * nst
        for s in range(nst):
            key = (block_of[s], tuple(block_of[trans[s][a]] for a in range(n)))
            if key not in sig:
                sig[key] = len(sig)
            block_of2[s] = sig[key]
        if len(sig) == nblocks:
            break
        nblocks = len(sig)
        block_of = block_of2
    qtrans = []
    qacc = []
    for b in range(nblocks):
        rep = [s for s in range(nst) if block_of[s] == b][0]
        qtrans.append([block_of[trans[rep][a]] for a in range(n)])
        qacc.append(acc[rep])
    # canonical numbering by BFS in alphabet order
    label = [-1] * nblocks
    label[0] = 0
    order = [0]
    dq = [0]
    while dq:
        b = dq.pop(0)
        for a in range(n):
            t = qtrans[b][a]
            if label[t] < 0:
                label[t] = len(order)
                order.append(t)
                dq.append(t)
    return ([[label[qtrans[b][a]] for a in range(n)] for b in order],
            [qacc[b] for b in order])


def ref_distance(nexts, acc, n):
    nst = len(nexts)
    dist = [None] * nst
    dq = []
    for s in range(nst):
        if acc[s]:
            dist[s] = 0
            dq.append(s)
    rev = [[] for _ in range(nst)]
    for s in range(nst):
        for a in range(n):
            rev[nexts[s][a]].append(s)
    i = 0
    while i < len(dq):
        u = dq[i]
        i += 1
        for v in rev[u]:
            if dist[v] is None:
                dist[v] = dist[u] + 1
                dq.append(v)
    return dist


# ---------------------------------------------------------------- predicate

def ref_pred_atom(op, p, w):
    m = len(p)
    if op == 'match':
        return w == list(p)
    if op == 'startswith':
        if m == 0:
            return True
        return len(w) >= m and w[:m] == list(p)
    if op == 'endswith':
        if m == 0:
            return True
        return len(w) >= m and w[len(w) - m:] == list(p)
    if op == 'contains':
        if m == 0:
            return True
        for i in range(len(w) - m + 1):
            if w[i:i + m] == list(p):
                return True
        return False
    raise AssertionError(op)


def ref_pred(node, w):
    op = node['op']
    if op == 'true':
        return True
    if op == 'false':
        return False
    if op == 'not':
        return not ref_pred(node['arg'], w)
    if op == 'and':
        return all(ref_pred(a, w) for a in node['args'])
    if op == 'or':
        return any(ref_pred(a, w) for a in node['args'])
    return ref_pred_atom(op, node['path'], w)


def ref_language_ok(services, rules, w):
    ok = any(ref_pred(r['when'], w) for r in rules if r['action'] == 'allow')
    if not ok:
        return False
    return not any(ref_pred(r['when'], w) for r in rules if r['action'] == 'drop')
