"""Randomized differential test: submission vs independent reference."""
import json
import random
import subprocess
import sys
import pathlib

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import ref_impl

TOKS = ['a', 'b', 'c', 'aa', 'ab', 'Î²', 'Ã', 'x y', '"q"', 'Z']


def run_main(lines):
    payload = b''.join(line + b'\n' for line in lines)
    with tempfile_dir() as cwd:
        run = subprocess.run([sys.executable, '-I',
                              str(pathlib.Path('/workspace/submission/main.py').resolve())],
                             cwd=cwd, input=payload, capture_output=True, timeout=120)
    return run


def tempfile_dir():
    import tempfile
    return tempfile.TemporaryDirectory()


def gen_request(rng):
    n = rng.randint(0, 4)
    services = rng.sample(TOKS, n)
    ntokens = rng.randint(1, 4)
    while len(services) < ntokens:
        services.append(rng.choice([t for t in TOKS if t not in services]))
    rng.shuffle(services)
    services = services[:max(n, ntokens)]
    rules = []
    nrules = rng.randint(0, 4)
    for _ in range(nrules):
        rules.append({'action': rng.choice(['allow', 'drop']),
                      'when': gen_expr(rng, services)})
    nq = rng.randint(0, 5)
    queries = [gen_query(rng, services) for _ in range(nq)]
    return {'services': services, 'rules': rules, 'queries': queries}


def gen_query(rng, services):
    return [rng.choice(services) for _ in range(rng.randint(0, 6))]


def gen_expr(rng, services, depth=0):
    choices = ['true', 'false', 'not', 'and', 'or', 'match', 'startswith',
               'endswith', 'contains']
    op = rng.choice(choices)
    if op in ('true', 'false'):
        return {'op': op}
    if op == 'not':
        return {'op': 'not', 'arg': gen_expr(rng, services, depth + 1)}
    if op in ('and', 'or'):
        k = rng.randint(0, 3)
        return {'op': op, 'args': [gen_expr(rng, services, depth + 1)
                                   for _ in range(k)]}
    m = rng.randint(0, 4)
    return {'op': op, 'path': [rng.choice(services) for _ in range(m)]}


def check_request(req, got):
    services = req['services']
    rules = req['rules']
    dfa = got['dfa']
    nexts = dfa['next']
    acc = dfa['accept']
    n = len(services)
    tidx = {s: i for i, s in enumerate(services)}
    problems = []
    # total + valid targets + reachability
    assert len(nexts) == len(acc) == len(dfa['distance'])
    for row in nexts:
        if len(row) != n:
            problems.append('row width')
        for t in row:
            if not (0 <= t < len(nexts)):
                problems.append('bad target')
    seen = set()
    stack = [0]
    while stack:
        s = stack.pop()
        if s in seen:
            continue
        seen.add(s)
        for t in nexts[s]:
            if t not in seen:
                stack.append(t)
    if len(seen) != len(nexts):
        problems.append('unreachable states')
    # language equivalence on all words up to a bound
    bound = 5
    words = [[]]
    for _ in range(bound):
        nxt = []
        for w in words:
            for s in services:
                nxt.append(w + [s])
        words.extend(nxt)
    def run_word(w):
        st = 0
        for tok in w:
            st = nexts[st][tidx[tok]]
        return acc[st]
    for w in words:
        want = ref_impl.ref_language_ok(services, rules, w)
        if run_word(w) != want:
            problems.append('language mismatch on %r' % (w,))
            break
    # minimality: distinct residuals via the predicate, bound = nstates + 2
    reach_word = {0: []}
    dq = [0]
    while dq:
        s = dq.pop(0)
        for a in range(n):
            t = nexts[s][a]
            if t not in reach_word:
                reach_word[t] = reach_word[s] + [services[a]]
                dq.append(t)
    k = len(nexts)
    lim = k + 2
    residuals = []
    for s in range(k):
        u = reach_word[s]
        accs = []
        stack = [[]]
        while stack:
            w = stack.pop()
            if ref_impl.ref_language_ok(services, rules, u + w):
                accs.append(1)
            else:
                accs.append(0)
            if len(w) < lim:
                for tok in services:
                    stack.append(w + [tok])
        residuals.append(tuple(accs))
    if len(set(residuals)) != k:
        problems.append('not minimal')
    # accept flag consistency at reaching words
    for s in range(k):
        if acc[s] != ref_impl.ref_language_ok(services, rules, reach_word[s]):
            problems.append('accept flag wrong at %d' % s)
    # distances via bounded predicate search
    for s in range(k):
        u = reach_word[s]
        d = dfa['distance'][s]
        if d is None:
            # verify no accepting state reachable in the DFA
            seen2 = set()
            st2 = [s]
            ok = True
            while st2:
                x = st2.pop()
                if x in seen2:
                    continue
                seen2.add(x)
                if acc[x]:
                    ok = False
                    break
                for t in nexts[x]:
                    if t not in seen2:
                        st2.append(t)
            if ok is False:
                problems.append('distance null but accepting reachable at %d' % s)
            if ref_impl.ref_language_ok(services, rules, u):
                problems.append('state %d accepts but distance null' % s)
        else:
            if d == 0:
                if not ref_impl.ref_language_ok(services, rules, u):
                    problems.append('distance 0 but not accepting at %d' % s)
            else:
                found = False
                stack = [[]]
                while stack:
                    w = stack.pop()
                    if len(w) == d:
                        if ref_impl.ref_language_ok(services, rules, u + w):
                            found = True
                            break
                        continue
                    for tok in services:
                        stack.append(w + [tok])
                if not found:
                    problems.append('distance %d too small at %d' % (d, s))
                # nothing shorter works
                stack = [[]]
                shorter = False
                while stack:
                    w = stack.pop()
                    if len(w) >= d:
                        continue
                    if ref_impl.ref_language_ok(services, rules, u + w):
                        shorter = True
                        break
                    for tok in services:
                        stack.append(w + [tok])
                if shorter:
                    problems.append('distance %d too big at %d' % (d, s))
    # queries
    for q, res in zip(req['queries'], got['queries']):
        st = 0
        for tok in q:
            st = nexts[st][tidx[tok]]
        if res['state'] != st or res['allow'] != acc[st] or \
                res['distance'] != dfa['distance'][st]:
            problems.append('query mismatch')
    return problems


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    lines = []
    reqs = []
    for _ in range(count):
        req = gen_request(rng)
        reqs.append(req)
        lines.append(json.dumps(req).encode())
    run = run_main(lines)
    if run.returncode:
        print('CRASH', run.stderr.decode()[:3000])
        return 1
    out = [json.loads(x) for x in run.stdout.decode().splitlines()]
    bad = 0
    for req, got in zip(reqs, out):
        if got.get('ok') is not True:
            print('unexpected error', got)
            bad += 1
            continue
        ref = ref_impl.ref_compile(req['services'], req['rules'], req['queries'])
        if ref != got:
            print('REF MISMATCH')
            print('req ', json.dumps(req))
            print('mine', json.dumps(got))
            print('ref ', json.dumps(ref))
            bad += 1
            continue
        probs = check_request(req, got)
        if probs:
            print('CHECK FAIL', probs[:3])
            print('req ', json.dumps(req))
            bad += 1
        if bad >= 3:
            break
    print('cases', count, 'failures', bad)
    return 1 if bad else 0


if __name__ == '__main__':
    raise SystemExit(main())
