"""Second fuzz generator: heavier structures, empty/repeated patterns."""
import json, random, sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import fuzz

TOKS = ['a', 'b', 'c', 'aa', 'ab', 'ba', 'bb', 'Î²', 'Ã', 'x y', '"q"', 'Z',
        'a b', '', 'Î»', 'æ¥æ¬', 'A', 'AB']

def gen_path(rng, services, maxlen):
    return [rng.choice(services) for _ in range(rng.randint(0, maxlen))]

def gen_expr(rng, services, depth=0):
    r = rng.random()
    if depth >= 3:
        r = min(r, 0.55)
    if r < 0.06:
        return {'op': 'true'}
    if r < 0.12:
        return {'op': 'false'}
    if r < 0.22:
        return {'op': 'not', 'arg': gen_expr(rng, services, depth + 1)}
    if r < 0.34:
        return {'op': 'and', 'args': [gen_expr(rng, services, depth + 1)
                                      for _ in range(rng.randint(0, 4))]}
    if r < 0.46:
        return {'op': 'or', 'args': [gen_expr(rng, services, depth + 1)
                                     for _ in range(rng.randint(0, 4))]}
    op = rng.choice(['match', 'startswith', 'endswith', 'contains',
                     'endswith', 'contains'])
    return {'op': op, 'path': gen_path(rng, services, rng.randint(0, 5))}

def gen_request(rng):
    n = rng.randint(1, 5)
    services = rng.sample(TOKS, n)
    rules = []
    for _ in range(rng.randint(0, 5)):
        rules.append({'action': rng.choice(['allow', 'allow', 'drop']),
                      'when': gen_expr(rng, services)})
    # occasionally add contradictory / trivial rules
    if rng.random() < 0.15:
        rules.append({'action': 'allow', 'when': {'op': 'true'}})
    if rng.random() < 0.15:
        rules.append({'action': 'drop', 'when': {'op': 'true'}})
    queries = [gen_path(rng, services, rng.randint(0, 7)) for _ in range(rng.randint(0, 6))]
    return {'services': services, 'rules': rules, 'queries': queries}

fuzz.gen_request = gen_request
fuzz.gen_expr = gen_expr
if __name__ == '__main__':
    raise SystemExit(fuzz.main())
