                not any(f(mask) for f in drop_fns)
            cache[mask] = got
        return got

    trans, accept = build_product(tables, truths, alpha, accept_of_mask)
    next_out, accept_out = canonical_dfa(trans, accept, alpha)
    distance = compute_distance(next_out, accept_out, alpha)

